FOR UPDATE

SELECT id, project_id, project_task_id, execution_contract_id, acceptance_type, activity_status, current_report_version_id, version, creator, create_time, updater, update_time, deleted, tenant_id FROM acc_acceptance WHERE tenant_id = #{query.tenantId} AND deleted = 0 AND project_id IN
#{projectId}
ORDER BY project_id, FIELD(acceptance_type, 'PRELIMINARY', 'FINAL'), id

mapper.update:
UPDATE acc_acceptance
SET activity_status = 'COMPLETED',
    version = version + 1,
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.acceptanceId}
  AND version = #{update.expectedVersion}
  AND activity_status = 'PENDING'
  AND deleted = 0
